#include "libs/yocto/yocto_trace.h"
#include <cstdio>
using namespace yocto;
int main(){scene_data s; s.cameras.push_back({});s.cameras[0].frame=lookat_frame({0,0,2},{0,0,0},{0,1,0});s.cameras[0].aspect=1;s.shapes.push_back({});s.shapes[0].positions={{-10,-10,0},{10,-10,0},{0,10,0}};s.shapes[0].triangles={{0,1,2}};s.materials.push_back({});s.materials[0].type=material_type::matte;s.materials[0].color={0.5f,0.5f,0.5f};s.instances.push_back({});s.instances[0].shape=0;s.instances[0].material=0;s.environments.push_back({});s.environments[0].emission={1,1,1};trace_params p;p.resolution=8;p.samples=8;p.bounces=3;p.noparallel=true;p.sampler=trace_sampler_type::path;auto b=make_trace_bvh(s,p);auto l=make_trace_lights(s,p);auto state=make_trace_state(s,p);for(int n=0;n<8;n++)trace_samples(state,s,b,l,p);double sum=0;for(auto c:state.image){if(!isfinite(c))return 1;sum+=c.x+c.y+c.z;}if(sum<=0||state.samples!=8)return 2;printf("PATH_RENDER samples=%d lights=%zu sum=%.9f\n",state.samples,l.lights.size(),sum);}
